contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool callerIsOwner) public payable {
        require(msg.sender != address(this));
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;
        if (callerIsOwner) {
            require(msg.sender == c.owner());
            try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        } else {
            require(msg.sender != c.owner());
            try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        }

        if (!callerIsOwner) {
            assert(reverted && address(c).balance == beforeBalance && c.depositsCount() == beforeDeposits);
        } else {
            if (!reverted) {
                assert(address(c).balance == 0);
            } else {
                assert(address(c).balance == beforeBalance && c.depositsCount() == beforeDeposits);
            }
        }
    }

    receive() external payable {}
}

