        c = _c;
    }

    receive() external payable {}

    function run(uint value) public payable {
        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount();
        address ownerBefore = c.owner();

        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && address(c).balance == balBefore && c.depositsCount() == countBefore && c.owner() == ownerBefore);
    }
}
